// =================
// Archive Interface
// =================

// Archive exposes the offloaded eventlog history and document versions for
// bulk export - e.g. building or rebuilding a search index over the full
// content set. Bodies are delivered as presigned URLs that the consumer
// fetches directly from object storage; the service only brokers the
// catalog and mints the URLs. Object keys and the presigning mechanism are
// internal: consumers address content by identity (uuid, version,
// chunk_id), never by storage key.
type Archive interface {
	// ListArchivedDocuments enumerates the latest archived version of every
	// document offloaded to the archive, for a current-state snapshot. Pair
	// it with a Content.GetNewDocuments tail from watermark_event_id to
	// reconstruct full current state.
	ListArchivedDocuments(context.Context, *ListArchivedDocumentsRequest) (*ListArchivedDocumentsResponse, error)

	// ListArchiveChunks lists archived eventlog chunks in order, for full
	// ordered replay of the history that precedes the hot log.
	ListArchiveChunks(context.Context, *ListArchiveChunksRequest) (*ListArchiveChunksResponse, error)

	// GetArchivedDocument returns a fresh presigned URL for a specific
	// archived document version. Used to resolve replay bodies and to
	// re-mint a URL a consumer let expire.
	GetArchivedDocument(context.Context, *GetArchivedDocumentRequest) (*GetArchivedDocumentResponse, error)
}

